import test from 'node:test';
import assert from 'node:assert/strict';
import {normaliseAtmosphere,rayleighOpticalDepth,directTransmission,cloudTransmissionFor,phaseRayleigh,phaseHG} from '../src/atmosphere.mjs';
import {physicalSkyState} from '../src/sky-state.mjs';
import {patatTwilight,moonSkyLuminance,surfaceMagnitudeToLuminance,luminanceToSurfaceMagnitude,createSkyModel,singleScatteredSun} from '../src/sky-background.mjs';
import {scintillationFactor,displayVisibility} from '../src/visibility.mjs';
const near=(a,b,t=1e-9)=>assert.ok(Math.abs(a-b)<=t,`${a} != ${b}`);
const night={sun:{altDeg:-30,azDeg:270,distanceAu:1},moon:{altDeg:-40,azDeg:90,phaseAngleDeg:90,distanceKm:384400},utcMs:0};
const base=()=>normaliseAtmosphere({});
test('CP6 defaults are explicit assumptions, not observed local weather',()=>{const a=base();assert.equal(a.pressureHpa,1013.25);assert.equal(a.pressureSource,'standard-atmosphere-estimate');assert.equal(a.aerosolTau550,.06);assert.equal(a.cloudTransmission,1);});
test('pressure and elevation affect molecular optical depth exactly once',()=>{const s=base(),h=normaliseAtmosphere({elevationM:2800}),p=normaliseAtmosphere({elevationM:2800,pressureHpa:1013.25});assert.ok(h.pressureHpa<s.pressureHpa);near(rayleighOpticalDepth(550,p),rayleighOpticalDepth(550,s));near(rayleighOpticalDepth(550,normaliseAtmosphere({pressureHpa:506.625}))/rayleighOpticalDepth(550,s),.5);});
test('molecular 550nm optical depth agrees with published polynomial',()=>near(rayleighOpticalDepth(550,base()),.008569*.55**-4*(1+.0113*.55**-2+.00013*.55**-4)));
test('invalid atmosphere and ambiguous cloud inputs rejected',()=>{for(const x of [{pressureHpa:NaN},{aerosolTau550:-1},{cloudTransmission:1.1},{cloudTransmission:.5,cloudOpticalDepth:1},{elevationM:20000}])assert.throws(()=>normaliseAtmosphere(x));});
test('direct attenuation finite at horizon and zero below it',()=>{const a=base();assert.ok(directTransmission(550,0,a)>0);assert.ok(directTransmission(550,0,a)<directTransmission(550,90,a));assert.equal(directTransmission(550,-1,a),0);});
test('blue extinction stronger; haze reduces transmitted source',()=>{const a=base();assert.ok(directTransmission(440,30,a)<directTransmission(700,30,a));assert.ok(directTransmission(550,45,normaliseAtmosphere({aerosolTau550:.5}))<directTransmission(550,45,a));});
test('cloud scalar and optical-depth inputs each attenuate only once',()=>{const a=base(),b=normaliseAtmosphere({cloudTransmission:.3});near(directTransmission(550,45,b)/directTransmission(550,45,a),.3);const c=normaliseAtmosphere({cloudOpticalDepth:1});assert.ok(cloudTransmissionFor({altDeg:10,azDeg:0},c)<cloudTransmissionFor({altDeg:90,azDeg:0},c));});
test('cloud map owns total cloud transmission instead of compounding scalar',()=>{const a=normaliseAtmosphere({cloudTransmission:.2});assert.equal(cloudTransmissionFor({altDeg:40,azDeg:0},a,()=>.7,0),.7);assert.throws(()=>cloudTransmissionFor({altDeg:40,azDeg:0},a,()=>2,0));});
test('phase functions integrate to unity and aerosol scattering is forward',()=>{for(const fn of [phaseRayleigh,c=>phaseHG(c,.76)]){let sum=0,n=20000;for(let i=0;i<n;i++)sum+=fn(-1+(i+.5)*2/n)*4*Math.PI/n;near(sum,1,2e-5);}assert.ok(phaseHG(.99,.76)>phaseHG(-.99,.76));});
test('physical solar state changes with location and time independent of calendar display',()=>{const o={utcMs:Date.parse('2026-01-15T02:00:00Z'),latDeg:28.54,lonDeg:-81.38};const a=physicalSkyState(o),b=physicalSkyState({...o,utcMs:o.utcMs+12*3600000}),c=physicalSkyState({...o,calendarMoon:{phase:1,altDeg:90}});assert.ok(a.sun.altDeg<0);assert.ok(b.sun.altDeg>0);assert.deepEqual(a,c);assert.ok(a.moon.phaseAngleDeg>=0&&a.moon.phaseAngleDeg<=180);});
test('topocentric lunar position differs by observer and supports backward seeks',()=>{const o={utcMs:Date.parse('2026-01-03T05:00Z'),latDeg:28.54,lonDeg:-81.38},a=physicalSkyState(o),b=physicalSkyState({...o,latDeg:-33.86,lonDeg:151.21});assert.notEqual(a.moon.raDeg,b.moon.raDeg);assert.deepEqual(physicalSkyState(o),a);assert.ok(a.moon.illuminatedFraction>.97);});
test('surface magnitude and luminance conversions round trip',()=>{for(const m of [-1,10,18,21.8,30])near(luminanceToSurfaceMagnitude(surfaceMagnitudeToLuminance(m)),m,1e-12);});
test('Patat total zenith V fit reproduces published coefficients in fitted range',()=>{for(const alt of [-5,-7,-10,-15]){const x=-alt-5;near(patatTwilight(alt).totalVMag,11.84+1.518*x-.057*x*x);assert.equal(patatTwilight(alt).inMeasuredDomain,true);}assert.equal(patatTwilight(-20).excessLuminance,0);});
test('twilight residual subtracts reference night floor, not counting it twice',()=>{const t=patatTwilight(-15);near(t.excessLuminance,Math.max(0,surfaceMagnitudeToLuminance(t.totalVMag)-surfaceMagnitudeToLuminance(21.6)));});
test('moon model agrees with original paper Table2, no arbitrary screen hole',()=>{const rows=[[30,[7216,1160,530,437,818]],[60,[3364,541,247,204,381]],[90,[1351,217,99,82,153]],[120,[391,63,29,24,44]]],rs=[5,30,60,90,120];for(const [phase,values] of rows)for(let i=0;i<rs.length;i++){const got=moonSkyLuminance({moonAltDeg:30,targetAltDeg:90-Math.abs(60-rs[i]),separationDeg:rs[i],phaseAngleDeg:phase,extinctionMag:.172})/(1e-5/Math.PI);assert.ok(Math.abs(got-values[i])/values[i]<.025,`${phase}/${rs[i]}=${got} expected ${values[i]}`);}});
test('moon below horizon or zero-scattering atmosphere contributes no lunar sky',()=>{const p={moonAltDeg:40,targetAltDeg:60,separationDeg:30,phaseAngleDeg:30,extinctionMag:.17};assert.equal(moonSkyLuminance({...p,moonAltDeg:-1}),0);assert.equal(moonSkyLuminance({...p,extinctionMag:0}),0);assert.ok(moonSkyLuminance(p)>moonSkyLuminance({...p,phaseAngleDeg:120}));});
test('lunar aureole is finite and continuous at branch transition',()=>{const p={moonAltDeg:40,targetAltDeg:60,separationDeg:0,phaseAngleDeg:0,extinctionMag:.17};assert.ok(Number.isFinite(moonSkyLuminance(p)));near(moonSkyLuminance({...p,separationDeg:10-1e-6}),moonSkyLuminance({...p,separationDeg:10+1e-6}),1e-6);});
test('single scattering has no solar light in deep night or vacuum',()=>{const a=base(),h={altDeg:70,azDeg:180};assert.deepEqual(singleScatteredSun(h,night,a).rgb,[0,0,0]);const vacuum=normaliseAtmosphere({pressureHpa:0,aerosolTau550:0,greyTau:0});assert.deepEqual(singleScatteredSun(h,{...night,sun:{...night.sun,altDeg:50}},vacuum).rgb,[0,0,0]);});
test('daylight single-scattering luminance positive and blue-rich away from Sun',()=>{const s=singleScatteredSun({altDeg:90,azDeg:0},{...night,sun:{...night.sun,altDeg:30}},base());assert.ok(s.luminance>100);assert.ok(s.rgb[2]>s.rgb[0]);});
test('time-dependent sky really becomes brighter in twilight and daylight',()=>{const h={altDeg:60,azDeg:170};const values=[-30,-12,-6,30].map(alt=>createSkyModel({...night,sun:{...night.sun,altDeg:alt}},{}).sample(h).luminance);for(let i=1;i<values.length;i++)assert.ok(values[i]>values[i-1],JSON.stringify(values));});
test('moon changes background by angular separation even outside camera',()=>{const sky=createSkyModel({...night,moon:{altDeg:60,azDeg:180,phaseAngleDeg:20,distanceKm:384400}},{});assert.ok(sky.sample({altDeg:60,azDeg:190}).moonLuminance>sky.sample({altDeg:60,azDeg:0}).moonLuminance);});
test('cloud background and source are distinct, explicit cloud glow can add light',()=>{const h={altDeg:90,azDeg:0},a=createSkyModel(night,{}).sample(h),b=createSkyModel(night,{cloudTransmission:.2}).sample(h),c=createSkyModel(night,{cloudTransmission:.2,cloudGlowCdM2:.01}).sample(h);near(b.luminance/a.luminance,.2,1e-9);assert.ok(c.luminance>a.luminance);});
test('zero clouds transmit no direct star and sky black without additive local light',()=>{const a=normaliseAtmosphere({cloudTransmission:0});assert.equal(directTransmission(550,50,a),0);assert.equal(createSkyModel(night,a).sample({altDeg:50,azDeg:90}).luminance,0);});
test('scintillation deterministic, bounded, zero-mean and exposure-averaged',()=>{const cfg={strength:.08,exposureSec:.01,apertureMm:6};let sum=0;for(let i=0;i<10000;i++){const x=scintillationFactor('HIP:91262',i/20,20,cfg);assert.ok(x>=.92&&x<=1.08);sum+=x;}near(sum/10000,1,.001);assert.equal(scintillationFactor(1,2,30,cfg),scintillationFactor(1,2,30,cfg));assert.equal(scintillationFactor(1,2,30,{...cfg,reducedMotion:true}),1);assert.ok(Math.abs(scintillationFactor(1,2,30,{...cfg,exposureSec:100})-1)<.002);});
test('display contrast declines against brighter background without altering source flux',()=>{const a=displayVisibility(.05,.001,12),b=displayVisibility(.05,100,.01);assert.ok(a.deltaSrgb>b.deltaSrgb);assert.equal(a.detectable,true);assert.equal(b.detectable,false);});
test('CP6 empirical twilight also vanishes in vacuum',()=>{const s=createSkyModel({...night,sun:{...night.sun,altDeg:-8}},{pressureHpa:0,aerosolTau550:0});assert.equal(s.sample({altDeg:90,azDeg:0}).solarLuminance,0);});
test('CP6 callers cannot bypass atmospheric validation with an internal marker',()=>assert.throws(()=>normaliseAtmosphere({__cp6Atmosphere:true,pressureHpa:-100})));
test('CP6 absorbing-only atmosphere cannot create scattered moonlight',()=>{const state={...night,moon:{...night.moon,altDeg:50,phaseAngleDeg:0}};const s=createSkyModel(state,{pressureHpa:0,aerosolTau550:0,greyTau:.2});assert.equal(s.sample({altDeg:60,azDeg:90}).moonLuminance,0);});
